'use client';
import {useEffect,useState} from 'react';import {createClient} from '@/lib/supabase/client';import AppShell from '@/components/app-shell';import type {Vendor} from '@/types/database';
export default function Vendors(){const [vendors,setVendors]=useState<Vendor[]>([]);const [q,setQ]=useState('');const [form,setForm]=useState({name:'',gst_number:'',contact_person:'',phone:'',email:'',default_credit_days:30});const [editing,setEditing]=useState<string|null>(null);async function load(){const {data}=await (await createClient()).from('vendors').select('*').order('name');setVendors((data||[]) as Vendor[])}useEffect(()=>{load()},[]);async function save(e:React.FormEvent){e.preventDefault();const sb=await createClient();if(editing)await sb.from('vendors').update(form).eq('id',editing);else{const {data:{user}}=await sb.auth.getUser();if(!user)return;await sb.from('vendors').insert({...form,user_id:user.id})}setEditing(null);setForm({name:'',gst_number:'',contact_person:'',phone:'',email:'',default_credit_days:30});load()}async function archive(id:string){await (await createClient()).from('vendors').update({active:false}).eq('id',id);load()}const filtered=vendors.filter(v=>v.active&&(`${v.name} ${v.gst_number||''} ${v.phone||''}`).toLowerCase().includes(q.toLowerCase()));return <AppShell><div className="flex items-center justify-between mb-6"><div><h1 className="text-3xl font-bold">Vendors</h1><p className="text-zinc-500 mt-1">Manage your vendor directory.</p></div></div><div className="grid xl:grid-cols-3 gap-5"><form onSubmit={save} className="glass rounded-2xl p-5 space-y-3 h-fit"><h2 className="font-semibold mb-3">{editing?'Edit Vendor':'Add Vendor'}</h2>{[['name','Vendor name',true],['gst_number','GST number',false],['contact_person','Contact person',false],['phone','Phone',false],['email','Email',false]].map(([key,ph,req])=><input key={key as string} className="input" placeholder={ph as string} required={!!req} value={(form as any)[key as string]} onChange={e=>setForm({...form,[key as string]:e.target.value})}/>)}<input className="input" type="number" min="0" placeholder="Default credit days" value={form.default_credit_days} onChange={e=>setForm({...form,default_credit_days:Number(e.target.value)})}/><div className="flex gap-2"><button className="btn btn-primary flex-1">{editing?'Update':'Add Vendor'}</button>{editing&&<button type="button" className="btn btn-muted" onClick={()=>{setEditing(null);setForm({name:'',gst_number:'',contact_person:'',phone:'',email:'',default_credit_days:30})}}>Cancel</button>}</div></form><section className="glass rounded-2xl overflow-hidden xl:col-span-2"><div className="p-4 border-b border-zinc-800"><input className="input" placeholder="Search vendor…" value={q} onChange={e=>setQ(e.target.value)}/></div><div className="divide-y divide-zinc-800">{filtered.map(v=><div key={v.id} className="p-4 flex items-center justify-between gap-4"><div><p className="font-semibold">{v.name}</p><p className="text-xs text-zinc-500">{v.contact_person||'No contact'} · {v.phone||'No phone'} · {v.default_credit_days} days</p></div><div className="flex gap-2"><button className="btn btn-muted text-sm" onClick={()=>{setEditing(v.id);setForm({name:v.name,gst_number:v.gst_number||'',contact_person:v.contact_person||'',phone:v.phone||'',email:v.email||'',default_credit_days:v.default_credit_days})}}>Edit</button><button className="btn text-sm bg-red-500/10 text-red-300" onClick={()=>archive(v.id)}>Archive</button></div></div>)}{filtered.length===0&&<div className="p-8 text-center text-zinc-500">No vendors found.</div>}</div></section></div></AppShell>}
